                  aria-current={n.id === current?.id}
                  className={`mb-1 w-full rounded-md px-3 py-2 text-left ${n.id === current?.id ? 'bg-sel' : 'hover:bg-line/50'}`}
                >
                  <div className="flex items-center gap-1 text-sm font-medium">
